{"code": "import os, time, subprocess

now = time.time()
cutoff = now - (30 * 86400)
backup_dir = '/home/bob/backups'
for name in os.listdir(backup_dir):
    path = os.path.join(backup_dir, name)
    if os.path.isfile(path) and name.startswith('hermes-') and name.endswith('.tar.gz'):
        mtime = os.path.getmtime(path)
        if mtime < cutoff:
            print(f'Removing old backup file: {path}')
            os.remove(path)
    elif os.path.isdir(path) and name.startswith('hermes-'):
        mtime = os.path.getmtime(path)
        if mtime < cutoff:
            print(f'Removing old backup directory: {path}')
            subprocess.run(['rm', '-rf', path])"}
